const text = $('Telegram Trigger').first().json.message.text.trim();
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const firstName = $('Telegram Trigger').first().json.message.from.first_name || '';
const username = $('Telegram Trigger').first().json.message.from.username || '';

return [{
  json: {
    chat_id: chatId,
    text: text,
    first_name: firstName,
    username: username,
    is_start: text === '/start' ? 'yes' : 'no'
  }
}];

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const seq = String(Math.floor(Math.random() * 999) + 1).padStart(3, '0');
const sessionId = `SS-${dateStr}-${seq}`;

const input = $('Check Message Type').first().json;

return [{
  json: {
    session_id: sessionId,
    telegram_user_id: String(input.chat_id),
    client_name: input.first_name,
    client_username: input.username,
    stage: 'awaiting_situation',
    collected_data: JSON.stringify({}),
    created_at: now.toISOString(),
    updated_at: now.toISOString()
  }
}];

const input = $('Check Message Type').first().json;
const rows = $('Lookup Session').all().map(i => i.json);
const validRows = rows.filter(r => r.session_id);

const active = validRows.find(r =>
  String(r.telegram_user_id) === String(input.chat_id) &&
  r.stage !== 'completed'
);

if (!active) {
  return [{ json: { has_session: 'no', chat_id: input.chat_id } }];
}

let collected = {};
try {
  collected = JSON.parse(active.collected_data || '{}');
} catch(e) {
  collected = {};
}

return [{
  json: {
    has_session: 'yes',
    session_id: active.session_id,
    stage: active.stage,
    collected_data: collected,
    chat_id: input.chat_id,
    text: input.text,
    first_name: input.first_name,
    username: input.username,
    row_number: active.row_number
  }
}];

const input = $('Find Active Session').first().json;
const situation = input.text;

const collected = input.collected_data || {};
collected.situation = situation;

const prompt = `Ты — ассистент юридической фирмы. Клиент описал свою ситуацию. Твоя задача — оценить, достаточно ли информации для классификации обращения.

Ситуация клиента:
"${situation}"

Проанализируй и ответь строго в JSON:
{
  "needs_clarification": true/false,
  "clarification_questions": ["вопрос 1", "вопрос 2"],
  "reasoning": "почему нужны/не нужны уточнения"
}

Правила:
- needs_clarification = true, если не хватает ключевых фактов для определения типа дела, срочности или сложности
- Максимум 2 вопроса, короткие и конкретные
- Примеры уточнений: наличие судебной повестки, сроки давности, сумма спора, есть ли договор, количество сторон
- Если ситуация описана достаточно подробно — ставь false, не задавай вопросы ради вопросов
- Отвечай строго JSON, без markdown-обёрток`;

const requestBody = JSON.stringify({
  model: 'deepseek-v4-flash',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: 'Ты — JSON-генератор. Отвечай только валидным JSON без обёрток.' },
    { role: 'user', content: prompt }
  ]
});

return [{
  json: {
    chat_id: input.chat_id,
    session_id: input.session_id,
    row_number: input.row_number,
    first_name: input.first_name,
    username: input.username,
    collected_data: collected,
    request_body: requestBody
  }
}];

const input = $('Build LLM Assessment').first().json;
const raw = $('LLM Assessment').first().json.choices[0].message.content;

let parsed;
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { needs_clarification: false, clarification_questions: [], reasoning: 'parse error' };
}

return [{
  json: {
    chat_id: input.chat_id,
    session_id: input.session_id,
    row_number: input.row_number,
    first_name: input.first_name,
    username: input.username,
    collected_data: input.collected_data,
    needs_clarification: parsed.needs_clarification ? 'yes' : 'no',
    questions: parsed.clarification_questions || [],
    reasoning: parsed.reasoning || ''
  }
}];

const input = $('Parse Assessment').first().json;
const questions = input.questions;

let text = '🔍 Чтобы точнее направить ваше обращение, уточните, пожалуйста:\n\n';
questions.forEach((q, i) => {
  text += `${i + 1}. ${q}\n`;
});
text += '\nОтветьте одним сообщением.';

const sendBody = JSON.stringify({
  chat_id: input.chat_id,
  text: text
});

return [{
  json: {
    chat_id: input.chat_id,
    session_id: input.session_id,
    row_number: input.row_number,
    first_name: input.first_name,
    username: input.username,
    collected_data: input.collected_data,
    reply_text: text,
    new_stage: 'awaiting_clarification_1',
    send_body: sendBody
  }
}];

const input = $('Find Active Session').first().json;
const answer = input.text;

const collected = input.collected_data || {};
if (input.stage === 'awaiting_clarification_1') {
  collected.clarification_1 = answer;
} else {
  collected.clarification_2 = answer;
}

const contextParts = [];
if (collected.situation) contextParts.push(`Описание ситуации: "${collected.situation}"`);
if (collected.clarification_1) contextParts.push(`Ответ на уточнения: "${collected.clarification_1}"`);
if (collected.clarification_2) contextParts.push(`Дополнительные уточнения: "${collected.clarification_2}"`);

const prompt = `Ты — ассистент юридической фирмы. Проанализируй обращение клиента и классифицируй его.

${contextParts.join('\n')}

Ответь строго в JSON:
{
  "case_type": "family|labor|property|corporate|consumer|other",
  "urgency": "low|medium|high",
  "complexity": "low|medium|high",
  "summary": "2-3 предложения — суть ситуации",
  "key_facts": ["факт 1", "факт 2", "факт 3"],
  "attention_points": "на что обратить внимание юристу (сроки, риски, особенности)"
}

Правила:
- case_type: family (развод, алименты, опека), labor (увольнение, зарплата, трудовой спор), property (недвижимость, наследство, раздел имущества), corporate (регистрация, договоры между компаниями), consumer (возврат товара, некачественная услуга), other (не подходит ни одна)
- urgency high: есть судебная повестка, истекают сроки, угроза потери имущества/прав
- urgency medium: ситуация развивается, но нет немедленной угрозы
- urgency low: консультативный вопрос, нет сроков
- complexity high: несколько сторон, крупная сумма, судебное разбирательство
- complexity medium: спор между двумя сторонами, средняя сумма
- complexity low: типовая ситуация, консультация
- summary на русском языке
- key_facts — массив строк, 2-5 фактов
- Строго JSON без обёрток`;

const requestBody = JSON.stringify({
  model: 'deepseek-v4-flash',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: 'Ты — JSON-генератор. Отвечай только валидным JSON без обёрток.' },
    { role: 'user', content: prompt }
  ]
});

return [{
  json: {
    chat_id: input.chat_id,
    session_id: input.session_id,
    row_number: input.row_number,
    first_name: input.first_name,
    username: input.username,
    collected_data: collected,
    original_text: contextParts.join(' | '),
    request_body: requestBody
  }
}];

const input = $('Parse Assessment').first().json;
const collected = input.collected_data || {};

const contextParts = [];
if (collected.situation) contextParts.push(`Описание ситуации: "${collected.situation}"`);

const prompt = `Ты — ассистент юридической фирмы. Проанализируй обращение клиента и классифицируй его.

