const requestBody = JSON.stringify({
  model: 'deepseek-v4-flash',
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: 'Ты — JSON-генератор. Отвечай только валидным JSON без обёрток.' },
    { role: 'user', content: prompt }
  ]
});

return [{
  json: {
    chat_id: input.chat_id,
    session_id: input.session_id,
    row_number: input.row_number,
    first_name: input.first_name,
    username: input.username,
    collected_data: collected,
    original_text: collected.situation || '',
    request_body: requestBody
  }
}];

const raw = $('LLM Final Analysis').first().json.choices[0].message.content;

// Находим источник данных (одна из двух нод сработала)
let inputData = {};
try {
  const d = $('Process Clarification').first().json;
  if (d && d.session_id) inputData = d;
} catch(e) {}
if (!inputData.session_id) {
  try {
    const d = $('Build Final Prompt').first().json;
    if (d && d.session_id) inputData = d;
  } catch(e) {}
}

let parsed;
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = {
    case_type: 'other', urgency: 'medium', complexity: 'medium',
    summary: 'Не удалось обработать автоматически',
    key_facts: [], attention_points: 'Требуется ручной разбор'
  };
}

const now = new Date();
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const seq = String(Math.floor(Math.random() * 999) + 1).padStart(3, '0');

return [{
  json: {
    inquiry_id: `LS-${dateStr}-${seq}`,
    date: now.toISOString().slice(0, 10),
    session_id: inputData.session_id || '',
    client_name: inputData.first_name || '',
    client_username: inputData.username || '',
    client_telegram_id: String(inputData.chat_id || ''),
    case_type: parsed.case_type,
    urgency: parsed.urgency,
    complexity: parsed.complexity,
    summary: parsed.summary,
    key_facts: Array.isArray(parsed.key_facts) ? parsed.key_facts.join('; ') : String(parsed.key_facts),
    attention_points: parsed.attention_points || '',
    original_text: inputData.original_text || '',
    status: 'new',
    created_at: now.toISOString(),
    chat_id: inputData.chat_id,
    row_number: inputData.row_number,
    collected_data: inputData.collected_data
  }
}];

const inquiry = $('Parse Final Analysis').first().json;
const lawyers = $('Get Lawyers').all().map(i => i.json).filter(l => l.lawyer_id);

const available = lawyers.filter(l =>
  l.status === 'available' &&
  l.specializations &&
  l.specializations.split(',').map(s => s.trim()).includes(inquiry.case_type)
);

let matched = null;

if (available.length > 0) {
  available.sort((a, b) => (Number(a.active_cases) || 0) - (Number(b.active_cases) || 0));
  matched = available[0];
}

if (!matched) {
  const anyAvailable = lawyers.filter(l => l.status === 'available');
  if (anyAvailable.length > 0) {
    anyAvailable.sort((a, b) => (Number(a.active_cases) || 0) - (Number(b.active_cases) || 0));
    matched = anyAvailable[0];
  }
}

const caseTypeLabels = {
  family: '👨‍👩‍👧 Семейное',
  labor: '💼 Трудовое',
  property: '🏠 Недвижимость/Имущество',
  corporate: '🏢 Корпоративное',
  consumer: '🛒 Защита прав потребителей',
  other: '📋 Иное'
};

const urgencyLabels = { low: '🟢 Низкая', medium: '🟡 Средняя', high: '🔴 Высокая' };
const complexityLabels = { low: '🟢 Низкая', medium: '🟡 Средняя', high: '🔴 Высокая' };

const caseLabel = caseTypeLabels[inquiry.case_type] || inquiry.case_type;
const urgLabel = urgencyLabels[inquiry.urgency] || inquiry.urgency;
const compLabel = complexityLabels[inquiry.complexity] || inquiry.complexity;

let lawyerMsg = `📋 Новое обращение ${inquiry.inquiry_id}\n\n`;
lawyerMsg += `👤 Клиент: ${inquiry.client_name}`;
if (inquiry.client_username) lawyerMsg += ` (@${inquiry.client_username})`;
lawyerMsg += `\n📁 Тип дела: ${caseLabel}\n`;
lawyerMsg += `⚡ Срочность: ${urgLabel}\n`;
lawyerMsg += `📊 Сложность: ${compLabel}\n\n`;
lawyerMsg += `📝 Суть: ${inquiry.summary}\n\n`;
lawyerMsg += `🔑 Ключевые факты: ${inquiry.key_facts}\n`;
if (inquiry.attention_points) {
  lawyerMsg += `\n⚠️ Внимание: ${inquiry.attention_points}`;
}

const keyboard = {
  inline_keyboard: [[
    { text: '✅ Взять', callback_data: `accept:${inquiry.inquiry_id}` },
    { text: '🔄 Передать', callback_data: `reassign:${inquiry.inquiry_id}` },
    { text: '❌ Отклонить', callback_data: `decline:${inquiry.inquiry_id}` }
  ]]
};

const sendBody = JSON.stringify({
  chat_id: matched ? matched.telegram_id : '',
  text: lawyerMsg,
  reply_markup: keyboard
});

const now = new Date();
const assignId = `AS-${now.toISOString().slice(0,10).replace(/-/g,'')}-${String(Math.floor(Math.random()*999)+1).padStart(3,'0')}`;

return [{
  json: {
    matched: matched ? 'yes' : 'no',
    lawyer_id: matched ? matched.lawyer_id : '',
    lawyer_name: matched ? matched.name : '',
    lawyer_telegram_id: matched ? matched.telegram_id : '',
    lawyer_row_number: matched ? matched.row_number : '',
    inquiry_id: inquiry.inquiry_id,
    chat_id: inquiry.chat_id,
    client_name: inquiry.client_name,
    send_body: sendBody,
    assignment_id: assignId,
    timestamp: now.toISOString()
  }
}];

