const cb = $('Telegram Trigger').first().json.callback_query;

if (!cb || !cb.data) {
  return [{ json: { action: 'none', inquiry_id: '', lawyer_chat_id: '', callback_id: '', message_id: '' } }];
}

const parts = cb.data.split(':');

return [{
  json: {
    action: parts[0],
    inquiry_id: parts[1] || '',
    lawyer_chat_id: cb.from.id,
    lawyer_name: cb.from.first_name || '',
    callback_id: cb.id,
    message_id: cb.message.message_id
  }
}];

const cb = $('Parse Callback').first().json;
const inquiry = $('Get Inquiry for Accept').first().json;

return [{
  json: {
    callback_id: cb.callback_id,
    message_id: cb.message_id,
    lawyer_chat_id: cb.lawyer_chat_id,
    inquiry_id: cb.inquiry_id,
    inquiry_row_number: inquiry.row_number,
    client_telegram_id: inquiry.client_telegram_id,
    client_name: inquiry.client_name,
    lawyer_name: cb.lawyer_name
  }
}];

const cb = $('Parse Callback').first().json;
const inquiry = $('Get Inquiry for Reassign').first().json;
const assignments = $('Get All Assignments').all().map(i => i.json).filter(a => a.assignment_id);
const lawyers = $('Get Lawyers Reassign').all().map(i => i.json).filter(l => l.lawyer_id);

// Юристы, которым уже назначали это обращение
const triedIds = assignments
  .filter(a => a.inquiry_id === cb.inquiry_id)
  .map(a => a.lawyer_id);

// Добавляем текущего юриста
triedIds.push(String(cb.lawyer_chat_id));

const caseType = inquiry.case_type;

// Ищем по специализации, исключая уже попробованных
let candidates = lawyers.filter(l =>
  l.status === 'available' &&
  !triedIds.includes(String(l.telegram_id)) &&
  l.specializations &&
  l.specializations.split(',').map(s => s.trim()).includes(caseType)
);

// Если нет по специализации — любой доступный
if (candidates.length === 0) {
  candidates = lawyers.filter(l =>
    l.status === 'available' &&
    !triedIds.includes(String(l.telegram_id))
  );
}

let next = null;
if (candidates.length > 0) {
  candidates.sort((a, b) => (Number(a.active_cases) || 0) - (Number(b.active_cases) || 0));
  next = candidates[0];
}

const caseTypeLabels = {
  family: '👨‍👩‍👧 Семейное', labor: '💼 Трудовое',
  property: '🏠 Недвижимость', corporate: '🏢 Корпоративное',
  consumer: '🛒 Потребители', other: '📋 Иное'
};
const urgencyLabels = { low: '🟢 Низкая', medium: '🟡 Средняя', high: '🔴 Высокая' };
const complexityLabels = { low: '🟢 Низкая', medium: '🟡 Средняя', high: '🔴 Высокая' };

let newSendBody = '';
if (next) {
  let msg = `📋 Переназначено: ${cb.inquiry_id}\n\n`;
  msg += `👤 Клиент: ${inquiry.client_name}`;
  if (inquiry.client_username) msg += ` (@${inquiry.client_username})`;
  msg += `\n📁 Тип: ${caseTypeLabels[inquiry.case_type] || inquiry.case_type}\n`;
  msg += `⚡ Срочность: ${urgencyLabels[inquiry.urgency] || inquiry.urgency}\n`;
  msg += `📊 Сложность: ${complexityLabels[inquiry.complexity] || inquiry.complexity}\n\n`;
  msg += `📝 ${inquiry.summary}\n🔑 ${inquiry.key_facts}`;
  if (inquiry.attention_points) msg += `\n⚠️ ${inquiry.attention_points}`;

  const kb = { inline_keyboard: [[
    { text: '✅ Взять', callback_data: `accept:${cb.inquiry_id}` },
    { text: '🔄 Передать', callback_data: `reassign:${cb.inquiry_id}` },
    { text: '❌ Отклонить', callback_data: `decline:${cb.inquiry_id}` }
  ]]};

  newSendBody = JSON.stringify({ chat_id: next.telegram_id, text: msg, reply_markup: kb });
}

const now = new Date();
const assignId = `AS-${now.toISOString().slice(0,10).replace(/-/g,'')}-${String(Math.floor(Math.random()*999)+1).padStart(3,'0')}`;

return [{
  json: {
    found_next: next ? 'yes' : 'no',
    next_lawyer_id: next ? next.lawyer_id : '',
    next_lawyer_name: next ? next.name : '',
    next_telegram_id: next ? next.telegram_id : '',
    inquiry_id: cb.inquiry_id,
    inquiry_row_number: inquiry.row_number,
    client_telegram_id: inquiry.client_telegram_id,
    callback_id: cb.callback_id,
    message_id: cb.message_id,
    lawyer_chat_id: cb.lawyer_chat_id,
    previous_lawyer_id: String(cb.lawyer_chat_id),
    action: cb.action === 'decline' ? 'declined' : 'reassigned',
    send_body: newSendBody,
    assignment_id: assignId,
    timestamp: now.toISOString()
  }
}];

